-- Do not edit by hand.
insert into public.decisions
  (number, statement, reason, status, decided_by_name, decided_at, origin, origin_ref)
overriding system value
values
  (214, 'Answers G15, G16 and the new G20 and G21, for wave 4. G15: the bot learns of GitHub events by reading the open pull requests on reconcile, with the token it already has; a webhook comes when a minute''s delay costs something. G16: a standing job never changes its own goal, scope, schedule or cap; a person changes them in the web app, each change kept. G20: the checker posts its review on the pull request as a comment, with a token that can only comment, and never approves; only a person merges (117). G21: every job has its own monthly cap in dollars ($10 unless set otherwise) and pauses itself at it; all jobs together stay inside the $100 a month of decision 11', 'Chosen in conversation, all as recommended', 'active', 'the owner', '2026-11-26T00:00:00Z', 'import', '214'),
  (215, 'Wave 4 is planned in `wave-4.md`: the job record and its scheduler (4.1), job management in the web app (4.2), the checker (4.3), a feature goal (4.4) and the dashboard home (4.5), in that order. Slice 4.1 is planned in `slice-4-1.md`: `jobs`, `job_wakes` and `job_events`; reconcile makes the built-in jobs, takes each due job once, checks its cap and logs every wake with its outcome and cost, silent ones included; capture and briefs become the first two kinds; `GET /v1/jobs` and `GET /v1/jobs/:name` read them', 'Asked for in conversation: "lets keep going" after wave 3. Capture and briefs already run on their own but cannot be seen, paused or capped; making them jobs first gives every later job the same record', 'active', 'the owner', '2026-11-26T00:00:00Z', 'import', '215')
on conflict (origin, origin_ref) where origin_ref is not null do nothing;
